import{_ as s,o as n,a as l,b as t}from"./app.C41L12d5.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬入辅助配置接口","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/cube_load_aux_config"},{"text":"SetLoadDataBoundary","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/SetLoadDataBoundary"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/SetLoadDataBoundary.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/SetLoadDataBoundary.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),e={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/SetLoadDataBoundary.md"};function p(i,a,c,d,o,r){return n(),l("div",null,[...a[0]||(a[0]=[t(`<div><article class="markdown-body"><h1>SetLoadDataBoundary<span id="ZH-CN_TOPIC_0000001787861430"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：不支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_mm_intf.h&quot;</code>。</p><p>设置<a href="../cube_compute_load/LoadData_3D.html">LoadData（卷积数据搬运）</a>接口所需的L1 Buffer（TPosition: A1/B1）边界值。</p><p>如果<a href="../cube_compute_load/LoadData_3D.html">LoadData（卷积数据搬运）</a>指令在处理源操作数时，源操作数在L1 Buffer（A1/B1）上的地址超出设置的边界，则会从L1 Buffer（A1/B1）起始地址开始读取数据。</p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetLoadDataBoundary</span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">boundaryValue</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>boundaryValue</td><td>输入</td><td>边界值：单位是Byte。<br>  • LoadData（卷积数据搬运）v1指令：单位是32字节。<br>  • LoadData（卷积数据搬运）v2指令：单位是字节。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>如果使用SetLoadDataBoundary接口设置了边界值，配合LoadData（卷积数据搬运）指令使用时，LoadData（卷积数据搬运）指令的L1 Buffer（A1/B1）的初始地址要在设置的边界内。</li><li>如果boundaryValue设置为0，则表示无边界，可使用整个L1 Buffer（A1/B1）。</li><li>配合<a href="../cube_compute_load/LoadData_3D.html">LoadData（卷积数据搬运）</a>指令使用时，边界值大小最小值要求是1024，如果设置1~1023值是未定义行为。</li><li>操作数地址对齐要求请参见<a href="../../../general_description_and_constraints.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="调用示例">调用示例<span id="section642mcpsimp"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>参考<a href="SetFmatrix.html#section642mcpsimp">调用示例</a>。</p><p>本接口用于配合<a href="../cube_compute_load/LoadData_3D.html">LoadData（卷积数据搬运）</a>接口使用，展示代码示例片段：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// LoadData（卷积数据搬运）指令完成img2col的过程，可知img2col后A矩阵高度为ho * wo，根据ho和wo的计算公式，代入卷积核宽度、卷积核滑动步长、卷积核膨胀系数等参数可知：A矩阵的高度为CeilAlign(k, fractalShape[0])；img2col后A矩阵宽度为ci * kh * kw，代入kh=1，kw=1，可知A矩阵的宽度为CeilAlign(m, fractalShape[1])。最后，配置loadDataParams.enTranspose = true，将整个A矩阵转置并且将其中每一个分形转置</span>
<span class="c1">// 使用load3d接口，实现NZ2ZZ</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData3DParamsV2</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">;</span>
<span class="c1">// 设置loadDataParams相关参数</span>
<span class="p">...</span>

<span class="c1">// SetLoadDataBoundary设置为0，可使用整个L1 Buffer</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetLoadDataBoundary</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData</span><span class="p">(</span><span class="n">a2Local</span><span class="p">,</span><span class="w"> </span><span class="n">a1Local</span><span class="p">,</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const _=s(e,[["render",p]]);export{u as __pageData,_ as default};
